import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA source code for fused add + HardSwish
fused_add_hardswish_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float hardswish_forward(float x) {
    if (x <= -3.0f) {
        return 0.0f;
    } else if (x >= 3.0f) {
        return x;
    } else {
        return x * (x + 3.0f) / 6.0f;
    }
}

__global__ void fused_add_hardswish_kernel(const float* x, const float* add, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx] + add[idx];
        float act = hardswish_forward(val);
        out[idx] = val * act;
    }
}

torch::Tensor fused_add_hardswish_cuda(torch::Tensor x, torch::Tensor add) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    fused_add_hardswish_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        add.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}
"""

# C++ declaration
fused_add_hardswish_cpp_source = r"""
torch::Tensor fused_add_hardswish_cuda(torch::Tensor x, torch::Tensor add);
"""

# Build and load fused operator
fused_add_hardswish = load_inline(
    name="fused_add_hardswish",
    cpp_sources=fused_add_hardswish_cpp_source,
    cuda_sources=fused_add_hardswish_source,
    functions=["fused_add_hardswish_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a 3D transposed convolution and fuses addition + HardSwish activation 
    into a custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding
        )
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.fused_add_hardswish = fused_add_hardswish

    def forward(self, x, add_input):
        x = self.conv_transpose(x)
        x = self.fused_add_hardswish.fused_add_hardswish_cuda(x, add_input)
        return x

