bias_shape = (out_channels, 1, 1, 1, 1)

def get_inputs():
    return [
        torch.randn(batch_size, in_channels, D, H, W),
        torch.randn(batch_size, out_channels, D * stride, H * stride, W * stride)
    ]

def get_init_inputs():
    return [
        in_channels,
        out_channels,
        kernel_size,
        stride,
        padding,
        output_padding,
        bias_shape
    ]
